def orbit(r,c,n=24):
    pts=set()
    for k in range(4):
        rr,cc=r,c
        for _ in range(k): rr,cc=cc,n-1-rr
        pts.add((rr,cc)); pts.add((rr,n-1-cc))
    return pts
